use std::f64::consts::PI;
unsafe fn fft(r:&mut [f64;32], im:&mut [f64;32], n:usize, inv:bool){let mut j=0usize;for i in 1..n{let mut bit=n>>1;while j&bit!=0{j^=bit;bit>>=1;}j^=bit;if i<j{r.swap(i,j);im.swap(i,j);}}let mut len=2;while len<=n{let a=(if inv{1.0}else{-1.0})*2.0*PI/(len as f64);let cr=a.cos();let ci=a.sin();let mut s=0;while s<n{let(mut wr,mut wi)=(1.0,0.0);for k in 0..len/2{let u=s+k;let v=u+len/2;let(pr,pi)=(wr*r[v]-wi*im[v],wr*im[v]+wi*r[v]);let(ur,ui)=(r[u],im[u]);r[u]=ur+pr;im[u]=ui+pi;r[v]=ur-pr;im[v]=ui-pi;let nr=wr*cr-wi*ci;wi=wr*ci+wi*cr;wr=nr;}s+=len;}len*=2;}if inv{for i in 0..n{r[i]/=n as f64;im[i]/=n as f64;}}}
fn quant(x:f64)->i64{let z=x*1_000_000.0;if z>=0.0{(z+0.5).floor() as i64}else{(z-0.5).ceil() as i64}}
#[no_mangle] pub unsafe extern "C" fn fft_bluestein(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<2||n>9{return -1;}let a=std::slice::from_raw_parts(v,n);let m=a[0];if !(1..=8).contains(&m)||n!=m as usize+1||a[1..].iter().any(|&x|!(-8..=8).contains(&x)){return -1;}let m=m as usize;let mut z=1usize;let need=3*m-2;while z<need{z*=2;}let bytes=16*m;if out.is_null()||cap<bytes{return -2;}let(mut ar,mut ai,mut br,mut bi)=([0.0;32],[0.0;32],[0.0;32],[0.0;32]);for j in 0..m{let x=-PI*(j*j) as f64/m as f64;ar[j]=a[j+1] as f64*x.cos();ai[j]=a[j+1] as f64*x.sin();}for k in 0..(2*m-1){let q=k as isize-(m as isize-1);let x=PI*(q*q) as f64/m as f64;br[k]=x.cos();bi[k]=x.sin();}fft(&mut ar,&mut ai,z,false);fft(&mut br,&mut bi,z,false);for i in 0..z{let x=ar[i]*br[i]-ai[i]*bi[i];ai[i]=ar[i]*bi[i]+ai[i]*br[i];ar[i]=x;}fft(&mut ar,&mut ai,z,true);for k in 0..m{let x=-PI*(k*k) as f64/m as f64;let(cr,ci)=(x.cos(),x.sin());let re=ar[k+m-1]*cr-ai[k+m-1]*ci;let im=ar[k+m-1]*ci+ai[k+m-1]*cr;for (q,val) in [quant(re),quant(im)].iter().enumerate(){let b=val.to_le_bytes();std::ptr::copy_nonoverlapping(b.as_ptr(),out.add(16*k+8*q),8);}}bytes as i64}
